  AK.def2d("I2-c", { title: "Labour — and rural–urban migration", label: "Farm labour supply", blurb: "Labour is human effort used in production; its reward is wages. Widen the gap between city and village life and watch farm labour leave.", vars: [{ key: "gap", label: "City wage ÷ farm wage", min: 1, max: 4, step: 0.1, value: 2.2 }, { key: "amen", label: "Village amenities (roads, power, schools)", min: 0, max: 100, step: 5, value: 30, unit: "%" }],
    run(c) { const out = []; let L = 100; for (let y = 0; y <= 10; y++) { out.push(L); const m = clamp(0.02 * (c.gap - 1) * (1 - c.amen / 140), 0, 0.12); L *= 1 - m; } return out; },
    draw(g, s, c, B) { const D = MK.scenes["I2-c"].run(c), A = AK.axes(B, B.area.x, 12, B.area.w, B.H - 26, { x0: 0, x1: 10, y0: 0, y1: 100, xl: "Years", yl: "Farm labour available (%)", title: "Labour on farms" }); B.poly(D.map((v, i) => [A.X(i), A.Y(v)]), B.P.blue, null, 2.6, false); const wage = 1500 * 100 / D[10];
      AK.side(B, "After 10 years: " + Math.round(D[10]) + " % of labour left", [["Daily farm wage rises to about " + N(wage) + " (from ₦1,500)", "#ffd27a", true], "Causes of migration: better jobs and pay in towns, amenities, education, drudgery of farm work, land shortage.", "Effects on farming: labour shortage, high wages, ageing farmers, less food produced.", "Solutions: rural amenities, mechanisation, credit, better prices, youth in agriculture programmes.", "Types of labour: family, hired, communal, exchange (cooperative)."]); },
    readouts: (s, c) => { const D = MK.scenes["I2-c"].run(c); return [["Labour after 10 years", Math.round(D[10]) + " %"], ["Farm wage", N(1500 * 100 / D[10])]]; }, tasks: ["How do better amenities change migration?", "Give four effects of rural–urban migration on agriculture.", "What is the reward for labour?"] });
  AK.def2d("I2-d", { title: "Management — the entrepreneur", label: "Rewards of the factors", blurb: "The entrepreneur combines land, labour and capital and bears the risk. Change the costs and see what is left as profit.", vars: [{ key: "rev", label: "Sales revenue", min: 500000, max: 3000000, step: 50000, value: 1800000, unit: "₦" }, { key: "rent", label: "Rent (land)", min: 0, max: 500000, step: 10000, value: 200000, unit: "₦" }, { key: "wage", label: "Wages (labour)", min: 0, max: 1200000, step: 10000, value: 600000, unit: "₦" }, { key: "int", label: "Interest (capital)", min: 0, max: 500000, step: 10000, value: 150000, unit: "₦" }],
    draw(g, s, c, B) { const p = c.rev - c.rent - c.wage - c.int, A = B.area, items = [["Rent", c.rent, B.P.green], ["Wages", c.wage, B.P.blue], ["Interest", c.int, B.P.purple], [p >= 0 ? "Profit" : "Loss", Math.abs(p), p >= 0 ? B.P.amber : B.P.red]]; AK.pie(B, A.x + A.w / 2, A.y + A.h / 2 + 6, Math.min(A.w, A.h) * 0.32, items);
      AK.side(B, (p >= 0 ? "Profit " : "Loss ") + N(Math.abs(p)), [["Profit = revenue − (rent + wages + interest)", "#ffd27a", true], "Functions of the entrepreneur: decides what, how and how much to produce; raises capital; combines the factors; bears risk; markets produce; keeps records.", "Rewards: land → rent · labour → wages · capital → interest · entrepreneur → profit."]); },
    readouts: (s, c) => [["Profit", N(c.rev - c.rent - c.wage - c.int)]], steps: (s, c) => ["Total cost = " + N(c.rent) + " + " + N(c.wage) + " + " + N(c.int) + " = " + N(c.rent + c.wage + c.int), "Profit = " + N(c.rev) + " − " + N(c.rent + c.wage + c.int) + " = " + N(c.rev - c.rent - c.wage - c.int)], tasks: ["Give five functions of the entrepreneur.", "Match each factor of production with its reward."] });

  /* ===================== I3 Demand ===================== */
  AK.def2d("I3-a", { title: "Definition of demand", label: "Willing and able to buy", blurb: "Demand is the quantity of a good consumers are willing and able to buy at a given price at a given time. Set the price and count the buyers.", vars: [{ key: "p", label: "Price of a basket of tomatoes", min: 500, max: 5000, step: 100, value: 2500, unit: "₦" }],
    draw(g, s, c, B) { const A = AR(B), n = 40; let buy = 0; for (let i = 0; i < n; i++) { const wtp = 600 + ((i * 7919) % n) / n * 4600, x = A.x + 10 + (i % 8) * (A.w - 20) / 8, y = A.y + 40 + Math.floor(i / 8) * 50, ok = wtp >= c.p; if (ok) buy++; B.circle(x + 14, y, 10, ok ? B.P.green : B.P.soft, ok ? "rgba(91,214,140,.5)" : null, 1.6); B.line(x + 14, y + 10, x + 14, y + 26, ok ? B.P.green : B.P.soft, 2); B.text("₦" + f(wtp / 1000, 2) + "k", x + 14, y + 40, { size: 9, align: "center", color: B.P.soft, halo: false }); } s.buy = buy; B.text("Each figure shows the most that buyer will pay", A.x, A.y + 14, { size: 11, color: B.P.soft });
      AK.side(B, buy + " buyers at " + N(c.p), [["Quantity demanded = " + buy * 2 + " baskets (2 each)", "#ffd27a", true], "Wanting is not demand: the buyer must also have money and be willing to spend it.", "Effective demand = desire + ability to pay + willingness to pay."]); },
    readouts: (s, c) => [["Price", N(c.p)], ["Buyers", s.buy || 0], ["Quantity demanded", (s.buy || 0) * 2]], tasks: ["Record quantity demanded at ₦1,000, ₦2,500 and ₦4,000.", "Define demand."] });
  AK.def2d("I3-b", { title: "Law of demand", label: "Demand curve", blurb: "Drag the point along the demand curve. The higher the price, the lower the quantity demanded, other things being equal.", values: { p: 2500 },
    pointer: MK.dragger((s, c, B) => { const A = s.A; return A ? [[A.X(Qd(c.p)), A.Y(c.p)]] : []; }, (i, p, s, c, B, H) => { const A = s.A; c.p = Math.round(clamp((A.py + A.ph - p.y) / A.ph * 6000, 300, 5000) / 100) * 100; }),
    vars: [{ key: "p", label: "Price", min: 300, max: 5000, step: 100, value: 2500, unit: "₦" }],
    draw(g, s, c, B) { const A = mkt(B, "Demand curve for tomatoes"); s.A = A; dcurve(B, A, 0, B.P.blue); B.text("D", A.X(Qd(400)) + 6, A.Y(400), { size: 13, w: 700, color: B.P.blue }); guide(B, A, Qd(c.p), c.p, B.P.red);
      AK.side(B, "Law of demand", [["At " + N(c.p) + ", quantity demanded = " + Math.round(Qd(c.p)) + " baskets", "#ffd27a", true], "The higher the price, the lower the quantity demanded, and the lower the price the higher the quantity demanded, ceteris paribus.", "The demand curve slopes downwards from left to right.", "Exceptions: goods of ostentation, Giffen goods, fear of future price rises."]); },
    table: () => sched((p) => Qd(p), [1000, 2000, 3000, 4000, 5000]), readouts: (s, c) => [["Price", N(c.p)], ["Quantity demanded", Math.round(Qd(c.p))]], tasks: ["Use the schedule to plot the demand curve.", "State the law of demand."] });
  const DF = [["inc", "Consumers' income", 1], ["sub", "Price of substitutes (e.g. garden egg)", 1], ["comp", "Price of complements (e.g. stew oil)", -1], ["pop", "Population", 1], ["taste", "Taste and fashion", 1], ["fest", "Season and festivals", 1]];
  AK.def2d("I3-c", { title: "Factors affecting demand for agricultural produce", label: "Shifting demand", blurb: "Raise or lower each factor. Price is held constant; the whole demand curve moves.", values: Object.fromEntries(DF.map(([k]) => [k, 0])),
    controls: DF.map(([k, n]) => ({ type: "range", key: k, label: n, min: -2, max: 2, step: 1, value: 0 })),
    draw(g, s, c, B) { const sd = DF.reduce((a, [k, , sg]) => a + c[k] * sg * 8, 0), A = mkt(B, "Demand for tomatoes"); dcurve(B, A, 0, B.P.soft, 1.6, [5, 4]); dcurve(B, A, sd, B.P.blue); B.text("D₀", A.X(Qd(400)) + 4, A.Y(400), { size: 12, color: B.P.soft }); B.text("D₁", A.X(clamp(Qd(400, sd), 2, 115)) + 4, A.Y(400) - 14, { size: 12, w: 700, color: B.P.blue }); guide(B, A, Qd(2500, sd), 2500, B.P.red);
      AK.side(B, sd > 0 ? "Demand increased" : sd < 0 ? "Demand decreased" : "No change", [["At ₦2,500: " + Math.round(Qd(2500)) + " → " + Math.round(Qd(2500, sd)) + " baskets", "#ffd27a", true], "Factors: price of the good itself (movement), income, prices of substitutes and complements, population, taste, season, advertisement, government policy, expectations of future prices."]); },
    readouts: (s, c) => [["Shift", f(DF.reduce((a, [k, , sg]) => a + c[k] * sg * 8, 0), 3) + " baskets"]], tasks: ["Which factors shift demand to the right when increased?", "Explain why demand for rice rises at Christmas."] });
  AK.def2d("I3-d", { title: "Movements along the demand curve", label: "Extension and contraction", blurb: "A change in the price of the good itself moves buyers along the same curve: extension when price falls, contraction when price rises.", vars: [{ key: "p1", label: "New price", min: 500, max: 5000, step: 100, value: 1500, unit: "₦" }],
    draw(g, s, c, B) { const A = mkt(B, "Movement along D"), p0 = 3000; dcurve(B, A, 0, B.P.blue); guide(B, A, Qd(p0), p0, B.P.soft); guide(B, A, Qd(c.p1), c.p1, B.P.red); if (c.p1 !== p0) B.arrow(A.X(Qd(p0)), A.Y(p0), A.X(Qd(c.p1)), A.Y(c.p1), B.P.amber, 2.4, 10);
      AK.side(B, c.p1 < p0 ? "Extension of demand" : c.p1 > p0 ? "Contraction of demand" : "Original point", [["Price ₦3,000 → " + N(c.p1) + ": quantity " + Math.round(Qd(p0)) + " → " + Math.round(Qd(c.p1)), "#ffd27a", true], "Only a change in the good's own price causes a movement along the curve.", "Other factors shift the whole curve."]); },
    readouts: (s, c) => [["Old price", N(3000)], ["New price", N(c.p1)], ["Change in quantity", Math.round(Qd(c.p1) - Qd(3000))]], tasks: ["Show an extension and a contraction of demand.", "What causes a movement along a demand curve?"] });
  AK.def2d("I3-e", { title: "Shifts in the demand curve", label: "Increase and decrease", blurb: "An increase in demand moves the curve right (more bought at every price). A decrease moves it left.", vars: [{ key: "sd", label: "Shift of demand", min: -40, max: 40, step: 5, value: 20, unit: "baskets" }],
    draw(g, s, c, B) { const A = mkt(B, "Shift of D"); dcurve(B, A, 0, B.P.soft, 1.6, [5, 4]); dcurve(B, A, c.sd, B.P.blue); [1500, 3000, 4500].forEach((p) => { if (c.sd) B.arrow(A.X(Qd(p)), A.Y(p), A.X(clamp(Qd(p, c.sd), 0, 120)), A.Y(p), B.P.amber, 1.8, 8); });
      AK.side(B, c.sd > 0 ? "Increase in demand (shift right)" : c.sd < 0 ? "Decrease in demand (shift left)" : "No shift", [["At every price, " + Math.abs(c.sd) + " baskets " + (c.sd >= 0 ? "more" : "fewer") + " are demanded", "#ffd27a", true], "Increase: higher income, more population, higher price of substitutes, favourable taste.", "Decrease: lower income, cheaper substitutes, change of taste away."]); },
    readouts: (s, c) => [["Shift", c.sd + " baskets"]], tasks: ["Draw a diagram showing an increase in demand.", "Distinguish a shift from a movement along the demand curve."] });

  /* ===================== I4 Supply ===================== */
  AK.def2d("I4-a", { title: "Definition of supply", label: "Farmers willing to sell", blurb: "Supply is the quantity of a good producers are willing and able to offer for sale at a given price at a given time.", vars: [{ key: "p", label: "Price of a basket of tomatoes", min: 500, max: 5000, step: 100, value: 2500, unit: "₦" }],
    draw(g, s, c, B) { const A = AR(B), n = 32; let sell = 0; for (let i = 0; i < n; i++) { const cost = 600 + ((i * 6151) % n) / n * 4000, x = A.x + 10 + (i % 8) * (A.w - 20) / 8, y = A.y + 40 + Math.floor(i / 8) * 64, ok = cost <= c.p; if (ok) sell++; B.g.fillStyle = ok ? "rgba(217,164,65,.6)" : "rgba(120,140,200,.15)"; B.g.fillRect(x, y, 30, 22); B.text("🍅", x + 15, y + 16, { size: 12, align: "center", halo: false }); B.text("₦" + f(cost / 1000, 2) + "k", x + 15, y + 38, { size: 9, align: "center", color: B.P.soft, halo: false }); } s.sell = sell; B.text("Each farmer's cost per basket — sells only if price covers it", A.x, A.y + 14, { size: 11, color: B.P.soft });
      AK.side(B, sell + " farmers sell at " + N(c.p), [["Quantity supplied = " + sell * 3 + " baskets (3 each)", "#ffd27a", true], "Supply is not the same as stock: stock is the total quantity in store; supply is the part offered for sale at a price."]); },
    readouts: (s, c) => [["Price", N(c.p)], ["Farmers selling", s.sell || 0], ["Quantity supplied", (s.sell || 0) * 3]], tasks: ["Define supply.", "Distinguish supply from stock."] });
  AK.def2d("I4-b", { title: "Law of supply", label: "Supply curve", blurb: "The higher the price, the greater the quantity supplied, other things being equal.", vars: [{ key: "p", label: "Price", min: 600, max: 5000, step: 100, value: 3000, unit: "₦" }],
    draw(g, s, c, B) { const A = mkt(B, "Supply curve for tomatoes"); scurve(B, A, 0, B.P.green); B.text("S", A.X(Qs(5500)) + 6, A.Y(5500), { size: 13, w: 700, color: B.P.green }); guide(B, A, Qs(c.p), c.p, B.P.red);
      AK.side(B, "Law of supply", [["At " + N(c.p) + ", quantity supplied = " + Math.round(Qs(c.p)) + " baskets", "#ffd27a", true], "The higher the price, the higher the quantity supplied; the lower the price, the lower the quantity supplied, ceteris paribus.", "The supply curve slopes upwards from left to right.", "Farm supply responds slowly because crops take time to grow (lag)."]); },
    table: () => sched((p) => Qs(p), [1000, 2000, 3000, 4000, 5000]), readouts: (s, c) => [["Price", N(c.p)], ["Quantity supplied", Math.round(Qs(c.p))]], tasks: ["Plot the supply schedule.", "State the law of supply."] });
  AK.def2d("I4-c", { title: "Movements along the supply curve", label: "Extension and contraction", blurb: "A change in the good's own price moves along the supply curve: extension when price rises, contraction when price falls.", vars: [{ key: "p1", label: "New price", min: 600, max: 5000, step: 100, value: 4200, unit: "₦" }],
    draw(g, s, c, B) { const A = mkt(B, "Movement along S"), p0 = 2500; scurve(B, A, 0, B.P.green); guide(B, A, Qs(p0), p0, B.P.soft); guide(B, A, Qs(c.p1), c.p1, B.P.red); if (c.p1 !== p0) B.arrow(A.X(Qs(p0)), A.Y(p0), A.X(Qs(c.p1)), A.Y(c.p1), B.P.amber, 2.4, 10);
      AK.side(B, c.p1 > p0 ? "Extension of supply" : c.p1 < p0 ? "Contraction of supply" : "Original point", [["Price ₦2,500 → " + N(c.p1) + ": quantity " + Math.round(Qs(p0)) + " → " + Math.round(Qs(c.p1)), "#ffd27a", true]]); },
    readouts: (s, c) => [["New price", N(c.p1)], ["Change in quantity", Math.round(Qs(c.p1) - Qs(2500))]], tasks: ["Show an extension of supply on a diagram."] });
  AK.def2d("I4-d", { title: "Shifts in the supply curve", label: "Increase and decrease", blurb: "An increase in supply moves the curve right; a decrease moves it left.", vars: [{ key: "ss", label: "Shift of supply", min: -40, max: 40, step: 5, value: -20, unit: "baskets" }],
    draw(g, s, c, B) { const A = mkt(B, "Shift of S"); scurve(B, A, 0, B.P.soft, 1.6, [5, 4]); scurve(B, A, c.ss, B.P.green); [1500, 3000, 4500].forEach((p) => { if (c.ss) B.arrow(A.X(clamp(Qs(p), 0, 120)), A.Y(p), A.X(clamp(Qs(p, c.ss), 0, 120)), A.Y(p), B.P.amber, 1.8, 8); });
      AK.side(B, c.ss > 0 ? "Increase in supply (shift right)" : c.ss < 0 ? "Decrease in supply (shift left)" : "No shift", [["At every price, " + Math.abs(c.ss) + " baskets " + (c.ss >= 0 ? "more" : "fewer") + " are supplied", "#ffd27a", true], "Increase: good weather, better technology, cheaper inputs, subsidies, more farmers.", "Decrease: drought, pests, high input prices, taxes."]); },
    readouts: (s, c) => [["Shift", c.ss + " baskets"]], tasks: ["Draw a decrease in supply caused by drought."] });
  const SF = [["wea", "Weather (good season)", 1], ["tech", "Technology (improved seed)", 1], ["inp", "Cost of inputs", -1], ["pest", "Pests and diseases", -1], ["sub", "Government subsidy", 1], ["alt", "Price of competing crops", -1]];
  AK.def2d("I4-e", { title: "Factors affecting supply of agricultural produce", label: "Shifting supply", blurb: "Change each factor and see the supply curve shift and the market price respond.", values: Object.fromEntries(SF.map(([k]) => [k, 0])),
    controls: SF.map(([k, n]) => ({ type: "range", key: k, label: n, min: -2, max: 2, step: 1, value: 0 })),
    draw(g, s, c, B) { const ss = SF.reduce((a, [k, , sg]) => a + c[k] * sg * 7, 0), A = mkt(B, "Supply of tomatoes"); dcurve(B, A, 0, B.P.blue, 2); scurve(B, A, 0, B.P.soft, 1.6, [5, 4]); scurve(B, A, ss, B.P.green); const E0 = eqm(0, 0), E = eqm(0, ss); guide(B, A, E0.Q, E0.P, B.P.soft); guide(B, A, E.Q, E.P, B.P.red);
      AK.side(B, ss > 0 ? "Supply increased" : ss < 0 ? "Supply decreased" : "No change", [["Market price " + N(E0.P) + " → " + N(E.P) + "; quantity " + Math.round(E0.Q) + " → " + Math.round(E.Q), "#ffd27a", true], "Factors: price of the product, cost of inputs, weather, technology, pests and diseases, prices of other products, government policy (taxes, subsidies), number of producers, storage and transport, time lag."]); },
    readouts: (s, c) => { const ss = SF.reduce((a, [k, , sg]) => a + c[k] * sg * 7, 0), E = eqm(0, ss); return [["Equilibrium price", N(E.P)], ["Quantity", Math.round(E.Q)]]; }, tasks: ["Explain how a drought affects the supply and price of maize.", "List six factors that affect supply of farm produce."] });

  /* ===================== I5 Price policy ===================== */
  AK.def2d("I5-a", { title: "Price support (minimum price)", label: "Price floor", blurb: "Government fixes a minimum price above equilibrium to protect farmers. Quantity supplied exceeds quantity demanded: a surplus.", vars: [{ key: "pf", label: "Minimum (floor) price", min: 2000, max: 5000, step: 100, value: 3600, unit: "₦" }],
    draw(g, s, c, B) { const A = mkt(B, "Price support"), E = eqm(); dcurve(B, A, 0, B.P.blue); scurve(B, A, 0, B.P.green); guide(B, A, E.Q, E.P, B.P.soft); const on = c.pf > E.P; B.line(A.X(0), A.Y(c.pf), A.X(120), A.Y(c.pf), B.P.red, 2.2); B.text("floor", A.X(118), A.Y(c.pf) - 6, { size: 10, align: "right", color: B.P.red }); if (on) { B.dot(A.X(Qd(c.pf)), A.Y(c.pf), B.P.blue, 5); B.dot(A.X(Qs(c.pf)), A.Y(c.pf), B.P.green, 5); B.dim(A.X(Qd(c.pf)), A.Y(c.pf), A.X(Qs(c.pf)), A.Y(c.pf), "surplus " + Math.round(Qs(c.pf) - Qd(c.pf)), B.P.amber, -18); }
      AK.side(B, on ? "Surplus " + Math.round(Qs(c.pf) - Qd(c.pf)) + " baskets" : "Floor below equilibrium — no effect", [["Equilibrium " + N(E.P) + ". Floor " + N(c.pf), "#ffd27a", true], "Effects: surplus; government must buy and store the excess (buffer stock) or export it; farmers' income protected; encourages production; consumers pay more.", "Cost to government ≈ " + N(on ? (Qs(c.pf) - Qd(c.pf)) * c.pf : 0)]); },
    readouts: (s, c) => [["Qd at floor", Math.round(Qd(c.pf))], ["Qs at floor", Math.round(Qs(c.pf))], ["Surplus", Math.max(0, Math.round(Qs(c.pf) - Qd(c.pf)))]], tasks: ["Calculate the surplus at a floor of ₦4,000.", "Why does government fix minimum prices for farm produce?"] });
  AK.def2d("I5-b", { title: "Price control (maximum price)", label: "Price ceiling", blurb: "Government fixes a maximum price below equilibrium to protect consumers. Quantity demanded exceeds quantity supplied: a shortage, and black markets appear.", vars: [{ key: "pc", label: "Maximum (ceiling) price", min: 600, max: 3200, step: 100, value: 1800, unit: "₦" }],
    draw(g, s, c, B) { const A = mkt(B, "Price control"), E = eqm(); dcurve(B, A, 0, B.P.blue); scurve(B, A, 0, B.P.green); guide(B, A, E.Q, E.P, B.P.soft); const on = c.pc < E.P; B.line(A.X(0), A.Y(c.pc), A.X(120), A.Y(c.pc), B.P.red, 2.2); B.text("ceiling", A.X(118), A.Y(c.pc) + 14, { size: 10, align: "right", color: B.P.red }); if (on) { B.dim(A.X(Qs(c.pc)), A.Y(c.pc), A.X(Qd(c.pc)), A.Y(c.pc), "shortage " + Math.round(Qd(c.pc) - Qs(c.pc)), B.P.amber, 18); const bm = Pd(Qs(c.pc)); B.dot(A.X(Qs(c.pc)), A.Y(bm), B.P.purple, 5); B.text("black-market price " + N(bm), A.X(Qs(c.pc)) + 8, A.Y(bm), { size: 10, color: B.P.purple }); }
      AK.side(B, on ? "Shortage " + Math.round(Qd(c.pc) - Qs(c.pc)) + " baskets" : "Ceiling above equilibrium — no effect", [["Equilibrium " + N(E.P) + ". Ceiling " + N(c.pc), "#ffd27a", true], "Effects: shortage; queues; rationing; hoarding; black market (illegal sales above the control price); farmers discouraged."]); },
    readouts: (s, c) => [["Shortage", Math.max(0, Math.round(Qd(c.pc) - Qs(c.pc)))], ["Black-market price", c.pc < eqm().P ? N(Pd(Qs(c.pc))) : "—"]], tasks: ["What is the black-market price when the ceiling is ₦1,500?", "List four effects of price control."] });
  AK.def2d("I5-c", { title: "Subsidy programme and its effects", label: "Input subsidy", blurb: "A subsidy on fertiliser lowers farmers' costs, shifting supply right. Prices fall and output rises; government pays the bill.", vars: [{ key: "sub", label: "Subsidy per basket", min: 0, max: 1500, step: 50, value: 600, unit: "₦" }],
    draw(g, s, c, B) { const A = mkt(B, "Effect of a subsidy"), ss = c.sub * DS.d, E0 = eqm(), E1 = eqm(0, ss); dcurve(B, A, 0, B.P.blue); scurve(B, A, 0, B.P.soft, 1.6, [5, 4]); scurve(B, A, ss, B.P.green); guide(B, A, E0.Q, E0.P, B.P.soft); guide(B, A, E1.Q, E1.P, B.P.red); B.text("S", A.X(Qs(5600)) - 10, A.Y(5600), { size: 12, color: B.P.soft }); B.text("S + subsidy", A.X(clamp(Qs(5600, ss), 0, 110)) + 4, A.Y(5600), { size: 11, w: 700, color: B.P.green });
      AK.side(B, "Subsidy " + N(c.sub) + " per basket", [["Price " + N(E0.P) + " → " + N(E1.P) + "; output " + Math.round(E0.Q) + " → " + Math.round(E1.Q), "#ffd27a", true], "Cost to government = " + N(c.sub * E1.Q), "Effects: cheaper inputs, more production, lower food prices, higher farm incomes, more adoption of new technology. Problems: cost to government, diversion and corruption, late delivery."]); },
    readouts: (s, c) => { const E1 = eqm(0, c.sub * DS.d); return [["New price", N(E1.P)], ["New quantity", Math.round(E1.Q)], ["Cost to government", N(c.sub * E1.Q)]]; }, tasks: ["Find the new price and output with a ₦1,000 subsidy.", "Give four effects of a fertiliser subsidy."] });

  /* ===================== I6–I7 Farm management ===================== */
  AK.tour("I6-a", Object.assign({}, FARM, { title: "Meaning of a farm manager", blurb: "Farm management is the organisation and running of a farm to make the best use of resources. The farm manager makes and carries out these decisions.", cam: [[0, 3.6, 7.6], [0, 0.4, 0]],
    build(g) { const h = AK.ground(g, { w: 14, d: 9, amp: 0.02 }); AK.put(g, AK.building("house", { w: 2, d: 1.4, h: 1.2 }), -3.4, -1.6, h); AK.put(g, AK.person({ shirt: 0x2a3a6a }), -2, 0.2, h, 0.4, 0.62); for (let i = 0; i < 3; i++) AK.put(g, AK.person({ shirt: [0xd8a040, 0x2a8a3a, 0x8a3a2a][i] }), 0.8 + i * 0.9, 0.4, h, -0.3, 0.58); AK.field(g, "maize", { x0: 0, x1: 6, z0: -3.6, z1: -1, dx: 0.5, dz: 0.5, stage: 0.7, h, s: 0.7 }); const t = AK.tractor(); t.scale.setScalar(0.5); AK.put(g, t, 4.6, 1.8, h, -0.5); },
    feats: [{ id: "mgr", n: "Farm manager", p: [-2, 1.4, 0.2], d: "Plans, organises, directs and controls all farm activities." }, { id: "work", n: "Farm workers", p: [1.7, 1.3, 0.4], d: "Carry out the manager's instructions." }, { id: "office", n: "Farm office and records", p: [-3.4, 1.8, -1.6], d: "Records, accounts and plans are kept here." }, { id: "res", n: "Resources", p: [3, 1.2, -2.3], d: "Land, capital, labour and machinery to combine." }],
    notes: ["Farm management = the science of making decisions on the use of farm resources to achieve the farmer's goals (usually maximum profit)."], tasks: ["Define farm management.", "Who is a farm manager?"] }));
  cards("I6-b", { title: "Functions of a farm manager", pick: "Function", head: "Functions of a farm manager", items: [["Planning", "Decides what, how, when and how much to produce; prepares farm plans and budgets."], ["Organising", "Brings land, labour, capital and inputs together in the right amounts."], ["Directing and supervising", "Assigns jobs to workers and supervises them."], ["Coordinating", "Ensures all sections and activities fit together."], ["Controlling", "Checks performance against plans and corrects problems."], ["Record keeping", "Keeps production, sales, labour and account records."], ["Marketing", "Decides when, where and how to sell produce."], ["Decision making and risk bearing", "Chooses between alternatives and bears the risk of loss."], ["Staff welfare and motivation", "Pays wages on time, trains and motivates workers."]], tasks: ["List eight functions of a farm manager.", "Explain planning and controlling."] });
  cards("I7-a", { title: "Problems faced by farm managers", pick: "Problem", head: "Problems and possible solutions", items: [["Inadequate capital", "Lack of money for inputs and machines.", "Solution: credit from agricultural banks, cooperatives, government grants."], ["Labour shortage", "Young people leave for towns.", "Solution: mechanisation, better wages, rural amenities."], ["Land tenure problems", "Small, scattered plots; insecure ownership.", "Solution: land reform, consolidation, leases."], ["Pests and diseases", "Losses of crops and animals.", "Solution: integrated pest management, vaccination, extension advice."], ["Poor marketing and low prices", "Middlemen, poor roads, price fluctuations.", "Solution: cooperatives, storage, processing, price support."], ["Weather uncertainty", "Drought, floods, storms.", "Solution: irrigation, insurance, resistant varieties, weather forecasts."], ["Inadequate storage and processing", "Post-harvest losses.", "Solution: silos, cribs, cold stores, processing plants."], ["Poor infrastructure", "Bad roads, no power or water.", "Solution: government investment, community action."], ["Low technical knowledge", "Poor adoption of new methods.", "Solution: extension services, training, farmers' groups."], ["Theft and insecurity", "Stolen produce and animals.", "Solution: fencing, guards, community policing, insurance."]], tasks: ["List six problems of farm managers and suggest solutions.", "How can cooperatives help farm managers?"] });

  /* ===================== I8 Agricultural finance ===================== */
  AK.def2d("I8-a", { title: "Meaning of agricultural finance", label: "Money flow", blurb: "Agricultural finance is the study of how farmers obtain, use and repay money (capital) for farm business. Watch the money flow.", tick: (dt, s) => { s.t = (s.t || 0) + dt; return true; },
    draw(g, s, c, B) { const A = AR(B), cx = A.x + A.w / 2, nodes = [["Sources (banks, co-ops, savings)", cx, A.y + 50, B.P.blue], ["Farmer", cx, A.y + A.h / 2, B.P.green], ["Uses (inputs, labour, machines)", A.x + 70, A.y + A.h - 50, B.P.amber], ["Produce sold → income", A.x + A.w - 70, A.y + A.h - 50, B.P.purple]]; const L = [[0, 1], [1, 2], [2, 3], [3, 1], [1, 0]]; L.forEach(([a, b], i) => { const P0 = nodes[a], P1 = nodes[b], off = (i === 4 ? 20 : i === 0 ? -20 : 0); B.arrow(P0[1] + off, P0[2] + 18, P1[1] + off, P1[2] - 18, "rgba(150,160,190,.6)", 1.6, 8); const u = ((s.t || 0) * 0.35 + i * 0.2) % 1; B.text("₦", P0[1] + off + (P1[1] - P0[1]) * u, P0[2] + 18 + (P1[2] - P0[2] - 36) * u, { size: 13, w: 700, color: B.P.amber }); }); nodes.forEach(([n, x, y, col]) => { B.circle(x, y, 18, col, null, 2.4); B.text(n, x, y + 34, { size: 10.5, align: "center", w: 700 }); }); B.text("repayment + interest", cx + 26, A.y + 120, { size: 10, color: B.P.soft });
      AK.side(B, "Agricultural finance", [["Obtaining capital → using it in production → repaying loans from farm income", "#ffd27a", true], "It covers credit (loans), savings, grants, investment and insurance in agriculture."]); },
    tasks: ["Define agricultural finance.", "Trace the flow of money in a farm business."] });
  AK.def2d("I8-b", { title: "Importance of agricultural finance", label: "Farm with and without credit", blurb: "Borrow money for improved inputs and compare output and profit with a farmer who has no credit.", vars: [{ key: "loan", label: "Loan amount", min: 0, max: 800000, step: 20000, value: 300000, unit: "₦" }, { key: "r", label: "Interest rate", min: 5, max: 40, value: 18, unit: "% per year" }],
    calc(c) { const base = 900000, extra = 2.4 * c.loan * Math.exp(-c.loan / 1200000); const rev = base + extra, cost = 500000 + c.loan * (1 + c.r / 100); return { base, rev, profit: rev - cost, p0: base - 500000 }; },
    draw(g, s, c, B) { const R = MK.scenes["I8-b"].calc(c); AK.barChart(B, B.area.x, 12, B.area.w, B.H - 26, [["Revenue (no loan)", R.base / 1000, B.P.soft], ["Revenue (loan)", R.rev / 1000, B.P.blue], ["Profit (no loan)", R.p0 / 1000, B.P.soft], ["Profit (loan)", R.profit / 1000, R.profit > R.p0 ? B.P.green : B.P.red]], { title: "₦ thousand", max: 2400, fmt: (v) => f(v, 3) + "k" });
      AK.side(B, R.profit > R.p0 ? "Credit pays: profit up " + N(R.profit - R.p0) : "Credit does not pay at this rate", [["Repay " + N(c.loan * (1 + c.r / 100)) + " (loan + interest)", "#ffd27a", true], "Importance: buys improved inputs and machines; expands farm size; adopts new technology; pays labour on time; stores produce for better prices; smooths income between seasons; raises output and income."]); },
    readouts: (s, c) => { const R = MK.scenes["I8-b"].calc(c); return [["Profit without loan", N(R.p0)], ["Profit with loan", N(R.profit)]]; }, tasks: ["At what interest rate does a ₦300,000 loan stop paying?", "Give six importance of agricultural finance."] });
  const SRC = [["Personal savings", 0, "No interest, no risk of debt, but usually small"], ["Family and friends", 0, "Cheap, flexible; amounts small"], ["Cooperative societies (thrift)", 8, "Low interest; members only"], ["Commercial banks", 25, "Large loans; need collateral; high interest"], ["Agricultural development banks (BOA, ADB)", 9, "Specialised; low interest; bureaucracy"], ["Government schemes (Anchor Borrowers)", 9, "Concessional loans with inputs"], ["Microfinance banks", 30, "Small loans, little collateral, high interest"], ["Money lenders", 60, "Quick, no paperwork; very high interest — exploitative"]];
  AK.def2d("I8-c", { title: "Sources of farm finance", label: "Compare lenders", blurb: "Pick a source and a loan size to compare the total cost of borrowing for one year.", values: { i: 2 }, vars: [{ key: "amt", label: "Amount borrowed", min: 20000, max: 1000000, step: 10000, value: 200000, unit: "₦" }],
    controls: [{ type: "select", key: "i", label: "Source", options: SRC.map((x, i) => [i, x[0]]) }],
    draw(g, s, c, B) { AK.barChart(B, B.area.x, 12, B.area.w, B.H - 26, SRC.map(([n, r], i) => [n.split(" (")[0].split(" ")[0] + (n.includes("bank") ? " bank" : ""), r, i === +c.i ? B.P.amber : B.P.blue]), { title: "Interest rate (% per year)", max: 70, fmt: (v) => v + "%" }); const S = SRC[+c.i];
      AK.side(B, S[0], [["Interest on " + N(c.amt) + " for 1 year: " + N(c.amt * S[1] / 100) + " (" + S[1] + " %)", "#ffd27a", true], S[2], "Other sources: NGOs, input suppliers (credit sales), produce buyers (advance payment), insurance companies."]); },
    readouts: (s, c) => [["Source", SRC[+c.i][0]], ["Interest", N(c.amt * SRC[+c.i][1] / 100)], ["Total repayment", N(c.amt * (1 + SRC[+c.i][1] / 100))]], tasks: ["Name eight sources of farm finance.", "Why do farmers avoid money lenders?"] });
  AK.def2d("I8-d", { title: "Classes of farm credit", label: "Loan calculator", blurb: "Credit is classified by duration (short, medium, long term), by security and by source. Set the loan and see the repayment schedule.", values: { m: "simple" },
    vars: [{ key: "P", label: "Principal", min: 50000, max: 2000000, step: 50000, value: 500000, unit: "₦" }, { key: "r", label: "Interest rate", min: 2, max: 30, value: 10, unit: "% p.a." }, { key: "n", label: "Duration", min: 1, max: 15, value: 3, unit: "years" }],
    controls: [{ type: "tabs", key: "m", label: "Interest", options: [["simple", "Simple"], ["comp", "Compound"]] }],
    amt: (c, y) => (c.m === "simple" ? c.P * (1 + c.r / 100 * y) : c.P * Math.pow(1 + c.r / 100, y)),
    draw(g, s, c, B) { const F = MK.scenes["I8-d"].amt, A = AK.axes(B, B.area.x, 12, B.area.w, B.H - 26, { x0: 0, x1: Math.max(c.n, 1), y0: 0, y1: F(c, c.n) * 1.1, nx: Math.min(c.n, 8), xl: "Years", yl: "Amount owed (₦)", title: "Growth of the debt" }); const bw = A.pw / (c.n + 1) * 0.5; for (let y = 0; y <= c.n; y++) { const v = F(c, y); g.fillStyle = y ? B.P.blue : B.P.green; g.fillRect(A.X(y) - bw / 2, A.Y(v), bw, A.Y(0) - A.Y(v)); } const cls = c.n <= 1 ? "Short-term (up to 1 year): seeds, fertiliser, feed, wages" : c.n <= 5 ? "Medium-term (1–5 years): livestock, small machines, fencing" : "Long-term (over 5 years): land, buildings, tree crops, tractors";
      AK.side(B, cls.split(":")[0], [[cls, "#ffd27a", true], "Amount after " + c.n + " years: " + N(F(c, c.n)) + " (interest " + N(F(c, c.n) - c.P) + ")", "By security: secured (collateral) vs unsecured. By lender: institutional vs non-institutional. By use: production, marketing, consumption."]); },
    steps: (s, c) => c.m === "simple" ? ["Simple interest I = P × R × T ÷ 100", "= " + N(c.P) + " × " + c.r + " × " + c.n + " ÷ 100 = " + N(c.P * c.r * c.n / 100), "Amount = P + I = " + N(c.P * (1 + c.r * c.n / 100))] : ["Compound amount A = P(1 + R/100)ⁿ", "= " + N(c.P) + " × (1 + " + c.r / 100 + ")^" + c.n, "= " + N(c.P * Math.pow(1 + c.r / 100, c.n)) + "; interest = " + N(c.P * Math.pow(1 + c.r / 100, c.n) - c.P)],
    readouts: (s, c) => { const F = MK.scenes["I8-d"].amt; return [["Class", c.n <= 1 ? "short-term" : c.n <= 5 ? "medium-term" : "long-term"], ["Total repayment", N(F(c, c.n))], ["Interest", N(F(c, c.n) - c.P)]]; }, tasks: ["Calculate the simple interest on ₦500,000 at 10 % for 3 years.", "Classify loans for buying a tractor, seeds and land.", "Compare simple and compound interest over 10 years."] });
  checklist("I8-e", { title: "Problems farmers face in getting credit", meter: "Chance of loan approval", head: "Does the farmer have…", on: ["rec", "grp"], items: [["coll", "Collateral (land title, property)", 30], ["rec", "Farm records and a business plan", 15], ["grp", "Membership of a cooperative", 15], ["lit", "Literacy / understands the forms", 10], ["near", "A bank branch nearby", 10], ["hist", "Good repayment history", 15], ["ins", "Crop or livestock insurance", 5]],
    verdict: (v) => (v >= 70 ? "Loan likely" : v >= 40 ? "Uncertain" : "Loan unlikely"), msg: (v) => (v >= 70 ? "The farmer meets most bank requirements." : "Missing items are the farmer's problems in getting credit."), foot: ["Problems: lack of collateral, high interest, illiteracy, bureaucracy and delays, distance to banks, small farm size, lack of records, short repayment periods, corruption."], tasks: ["List eight problems farmers face in getting credit.", "How can cooperatives help farmers get loans?"] });
  AK.def2d("I8-f", { title: "Problems institutions face in granting loans", label: "Lender's view", blurb: "Lend to 100 farmers. As defaults rise, the bank loses money and becomes unwilling to lend.", vars: [{ key: "def", label: "Default rate", min: 0, max: 50, value: 15, unit: "%" }, { key: "r", label: "Interest charged", min: 5, max: 35, value: 15, unit: "%" }, { key: "cost", label: "Admin cost per loan", min: 0, max: 30, value: 8, unit: "% of loan" }],
    draw(g, s, c, B) { const A = AR(B), n = 100; for (let i = 0; i < n; i++) { const x = A.x + 10 + (i % 10) * (A.w - 20) / 10, y = A.y + 34 + Math.floor(i / 10) * 26, bad = i < c.def; B.circle(x + 10, y, 8, bad ? B.P.red : B.P.green, bad ? "rgba(255,123,114,.45)" : "rgba(91,214,140,.45)", 1.4); } const ret = (100 - c.def) * (1 + c.r / 100) - 100 - c.cost; s.ret = ret; B.text("Red = defaulter, green = repays", A.x, A.y + 14, { size: 11, color: B.P.soft });
      AK.side(B, (ret >= 0 ? "Lender gains " : "Lender loses ") + f(Math.abs(ret), 3) + " % of the money lent", [["Return = repaid × (1 + r) − lent − admin costs", "#ffd27a", true], "Problems: loan default; lack of collateral; diversion of loans to other uses; high cost of small loans; risks from weather, pests and price falls; poor records; political interference; difficulty reaching rural farmers."]); },
    readouts: (s, c) => [["Defaulters", c.def + " of 100"], ["Lender's return", f(s.ret || 0, 3) + " %"]], steps: (s, c) => ["Repaid with interest = " + (100 - c.def) + " × " + f(1 + c.r / 100, 3) + " = " + f((100 - c.def) * (1 + c.r / 100), 4), "Return = " + f((100 - c.def) * (1 + c.r / 100), 4) + " − 100 − " + c.cost + " = " + f((100 - c.def) * (1 + c.r / 100) - 100 - c.cost, 4) + " %"], tasks: ["Find the default rate at which the bank breaks even at 15 % interest.", "List six problems institutions face in granting loans."] });
  AK.def2d("I8-g", { title: "Capital market and agri-business", label: "Agri-business value chain", blurb: "The capital market supplies long-term funds (shares, bonds) to businesses. Agri-business covers every firm along the chain from inputs to the consumer.", values: { i: 2 },
    controls: [{ type: "select", key: "i", label: "Link in the chain", options: [[0, "Input supply"], [1, "Production"], [2, "Processing"], [3, "Marketing"], [4, "Consumer"]] }],
    draw(g, s, c, B) { const A = AR(B), L = [["Input supply", "Seed, fertiliser, feed, machinery firms"], ["Production", "Farms and plantations"], ["Processing", "Mills, oil presses, canneries, abattoirs"], ["Marketing", "Wholesalers, exporters, supermarkets"], ["Consumer", "Households, industries"]]; const w = (A.w - 20) / 5; L.forEach(([n, d], i) => { const x = A.x + i * (w + 5), y = A.y + 60, on = i === +c.i; g.fillStyle = on ? "rgba(217,164,65,.35)" : "rgba(120,140,200,.15)"; g.fillRect(x, y, w, 70); B.text(n, x + w / 2, y + 40, { size: w < 70 ? 9.5 : 10.5, align: "center", w: 700, halo: false }); if (i < 4) B.arrow(x + w - 4, y + 35, x + w + 9, y + 35, B.P.ink, 1.6, 6); }); B.text("Capital market: shares and bonds → long-term funds for agri-businesses", A.x, A.y + 170, { size: 11, w: 700 }); ["Stock exchange", "Issuing houses", "Development banks", "Pension and insurance funds"].forEach((t, i) => { B.text("• " + t, A.x + 10, A.y + 196 + i * 18, { size: 11 }); });
      AK.side(B, L[+c.i][0], [[L[+c.i][1], "#ffd27a", true], "Agri-business = all activities in the production, processing, distribution and sale of agricultural products and inputs.", "Capital market = market for long-term loans and securities; money market = short-term funds."]); },
    tasks: ["Define agri-business and give examples at each stage.", "Distinguish the capital market from the money market."] });

  /* ===================== I9 Records and accounts ===================== */
  AK.def2d("I9-a", { title: "Importance of farm records", label: "Decisions with records", blurb: "Two poultry farmers decide which batch of birds to repeat. Only one keeps records. Turn records on to see what they reveal.", values: { rec: 1 },
    controls: [{ type: "toggle", key: "rec", label: "Records kept" }],
    draw(g, s, c, B) { const A = AR(B), rows = [["Batch", "Feed (kg)", "Deaths", "Sold (kg)", "Profit (₦)"], ["A — Hubbard", "4,200", "35", "4,900", "312,000"], ["B — Arbor Acres", "4,600", "12", "5,600", "498,000"], ["C — local", "2,900", "60", "2,100", "−45,000"]]; if (c.rec) AK.btable(B, A.x, A.y + 30, [110, 64, 52, 70, 70].map((w) => w * A.w / 372), rows, { hi: 2 }); else { B.text("No records: the farmer guesses…", A.x, A.y + 50, { size: 13, w: 700, color: B.P.red }); B.text("“Batch A felt best.”", A.x, A.y + 80, { size: 12, color: B.P.soft }); }
      AK.side(B, c.rec ? "Records show batch B is most profitable" : "Decisions are guesses", [["Importance of records:", "#ffd27a", true], "Show profit or loss; guide planning and decisions; help get loans and insurance; tax assessment; settle disputes; measure performance of animals and crops; detect waste and theft; help in sharing profits; inform extension and research."]); },
    tasks: ["Give eight importance of farm records.", "Which batch should the farmer repeat? Why?"] });
  const RECS = { inv: ["Inventory record", ["Item", "Qty", "Value (₦)", "Date"], [["Tractor", 1, "4,500,000", "Jan"], ["Sprayers", 3, "105,000", "Jan"], ["Hoes", 12, "36,000", "Jan"]]], prod: ["Production record", ["Date", "Crop / animal", "Output", "Unit"], [["Mar 2", "Layers", "870", "eggs"], ["Mar 3", "Layers", "885", "eggs"], ["Aug", "Maize", "3.2", "t"]]], sales: ["Sales record", ["Date", "Item", "Qty", "Amount (₦)"], [["Mar 5", "Eggs", "60 crates", "180,000"], ["Aug 20", "Maize", "2 t", "900,000"]]], pur: ["Purchases record", ["Date", "Item", "Qty", "Amount (₦)"], [["Feb 1", "Layer mash", "40 bags", "480,000"], ["Apr 6", "NPK", "10 bags", "220,000"]]], lab: ["Labour record", ["Name", "Days", "Rate (₦)", "Wages (₦)"], [["Ade", 22, "2,000", "44,000"], ["Ama", 20, "2,000", "40,000"]]], health: ["Health / vaccination record", ["Date", "Animals", "Treatment", "By"], [["Day 1", "Chicks", "Marek's vaccine", "Hatchery"], ["Day 21", "Chicks", "Gumboro", "Vet"]]], breed: ["Breeding record", ["Dam", "Sire", "Date served", "Due date"], [["Cow 12", "Bull 3", "Feb 10", "Nov 20"], ["Cow 7", "AI", "Mar 2", "Dec 10"]]], feed: ["Feeding record", ["Date", "Pen", "Feed (kg)", "Type"], [["Mar 1", "Pen A", "120", "Layer mash"], ["Mar 2", "Pen A", "122", "Layer mash"]]] };
  AK.def2d("I9-b", { title: "Types of farm records", label: "Record book", blurb: "Open each type of record in the farm record book.", values: { t: "inv" },
    controls: [{ type: "select", key: "t", label: "Record", options: Object.entries(RECS).map(([k, v]) => [k, v[0]]) }],
    draw(g, s, c, B) { const R = RECS[c.t], A = B.area; B.text(R[0], A.x, A.y + 18, { size: 14, w: 700 }); AK.btable(B, A.x, A.y + 34, R[1].map(() => (A.w - 6) / R[1].length), [R[1]].concat(R[2]), { rh: 24 }); AK.side(B, "Types of farm records", [["Inventory, production, sales, purchases, labour, feeding, health, breeding, input use, cash book, profit and loss account, balance sheet.", "#ffd27a", true], "Records should be accurate, up to date, simple and kept safely."]); },
    tasks: ["Name eight types of farm records.", "Draw a vaccination record for a poultry farm."] });
  AK.def2d("I9-c", { title: "Designing farm records — layer production record", label: "Build a record", blurb: "Fill in a week of a layer production record. The record works out hen-day production and feed per egg.", vars: [{ key: "hens", label: "Hens in the pen", min: 100, max: 2000, step: 50, value: 500 }, { key: "eggs", label: "Average eggs per day", min: 50, max: 1900, step: 10, value: 420 }, { key: "feed", label: "Feed per day", min: 10, max: 250, step: 1, value: 60, unit: "kg" }, { key: "dead", label: "Deaths this week", min: 0, max: 20, value: 2 }],
    draw(g, s, c, B) { const A = AR(B), d = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"], rows = [["Day", "Hens", "Eggs", "Feed (kg)", "Deaths"]]; let hens = c.hens, te = 0; d.forEach((dd, i) => { const dead = Math.floor(c.dead * (i + 1) / 7) - Math.floor(c.dead * i / 7); hens -= dead; const e = Math.max(0, Math.round(c.eggs * (1 + 0.04 * Math.sin(i * 1.7)))); te += e; rows.push([dd, hens, e, c.feed, dead]); }); rows.push(["Total", "", te, c.feed * 7, c.dead]); AK.btable(B, A.x, A.y + 30, [60, 64, 64, 80, 60].map((w) => w * (A.w - 6) / 328), rows, { rh: 22 }); B.text("Pen A — week 12", A.x, A.y + 16, { size: 12, w: 700 }); const hd = te / 7 / c.hens * 100; s.hd = hd; s.fpe = c.feed * 7 * 1000 / Math.max(1, te);
      AK.side(B, "Hen-day production " + f(hd, 3) + " %", [["Feed per egg = " + f(s.fpe, 3) + " g", "#ffd27a", true], "Hen-day % = average eggs per day ÷ hens × 100", hd > 75 ? "Good laying (over 75 %)." : hd > 55 ? "Fair laying." : "Poor laying: check feed, light, disease, age.", "A good record has a title, date, clear columns, units and totals."]); },
    readouts: (s, c) => [["Hen-day production", f(s.hd || 0, 3) + " %"], ["Feed per egg", f(s.fpe || 0, 3) + " g"]], steps: (s, c) => ["Hen-day % = " + c.eggs + " ÷ " + c.hens + " × 100 ≈ " + f(c.eggs / c.hens * 100, 4) + " %", "Feed per egg = " + c.feed + " kg × 1000 ÷ " + c.eggs + " = " + f(c.feed * 1000 / c.eggs, 4) + " g"], tasks: ["Design a production record for a layer pen.", "Calculate hen-day production for 500 hens laying 420 eggs a day."] });
  AK.def2d("I9-d", { title: "Farm accounts — depreciation and profit or loss", label: "Accounts", blurb: "Work out depreciation of a farm machine, then the profit and loss account for the year.", values: { m: "sl", v: "dep" },
    vars: [{ key: "cost", label: "Cost of machine", min: 200000, max: 6000000, step: 100000, value: 2400000, unit: "₦" }, { key: "salv", label: "Scrap (salvage) value", min: 0, max: 1000000, step: 50000, value: 400000, unit: "₦" }, { key: "life", label: "Useful life", min: 2, max: 15, value: 5, unit: "years" }, { key: "rate", label: "Reducing-balance rate", min: 5, max: 50, step: 5, value: 30, unit: "%" }, { key: "sales", label: "Sales for the year", min: 500000, max: 8000000, step: 100000, value: 3600000, unit: "₦" }, { key: "exp", label: "Other expenses for the year", min: 200000, max: 6000000, step: 100000, value: 2100000, unit: "₦" }],
    controls: [{ type: "tabs", key: "v", label: "View", options: [["dep", "Depreciation"], ["pl", "Profit and loss"]] }, { type: "tabs", key: "m", label: "Method", options: [["sl", "Straight line"], ["rb", "Reducing balance"]] }],
    dep: (c) => { const out = []; let bv = c.cost; for (let y = 1; y <= c.life; y++) { const d = c.m === "sl" ? (c.cost - c.salv) / c.life : bv * c.rate / 100; bv -= d; out.push([y, d, bv]); } return out; },
    draw(g, s, c, B) { const D = MK.scenes["I9-d"].dep(c), A0 = B.area; if (c.v === "dep") { const A = AK.axes(B, A0.x, 12, A0.w, B.H - 26, { x0: 0, x1: c.life, y0: 0, y1: c.cost, nx: Math.min(c.life, 8), xl: "Years", yl: "Book value (₦)", title: c.m === "sl" ? "Straight-line depreciation" : "Reducing-balance depreciation" }); B.poly([[A.X(0), A.Y(c.cost)]].concat(D.map(([y, , bv]) => [A.X(y), A.Y(Math.max(0, bv))])), B.P.blue, null, 2.6, false); D.forEach(([y, , bv]) => B.dot(A.X(y), A.Y(Math.max(0, bv)), B.P.blue, 3.5)); }
      else { const d1 = D[0][1], p = c.sales - c.exp - d1; AK.btable(B, A0.x, A0.y + 30, [A0.w * 0.62, A0.w * 0.36], [["Profit and loss account (year 1)", "₦"], ["Sales (income)", N(c.sales)], ["Less: operating expenses", N(c.exp)], ["Less: depreciation", N(d1)], ["Total expenses", N(c.exp + d1)], [p >= 0 ? "Net profit" : "Net loss", N(Math.abs(p))]], { rh: 26, hi: 5 }); }
      AK.side(B, c.m === "sl" ? "Straight line" : "Reducing balance", [["Year-1 depreciation " + N(D[0][1]) + "; book value after " + c.life + " years " + N(D[D.length - 1][2]), "#ffd27a", true], "Straight line: (cost − scrap) ÷ life, the same each year.", "Reducing balance: a fixed % of the remaining book value each year — larger at first.", "Net profit = income − (expenses + depreciation)."]); },
    table: (s, c) => "<table class='mk-t'><tr><th>Year</th><th>Depreciation</th><th>Book value</th></tr>" + MK.scenes["I9-d"].dep(c).map(([y, d, bv]) => `<tr><td>${y}</td><td>${N(d)}</td><td>${N(bv)}</td></tr>`).join("") + "</table>",
    steps: (s, c) => { const D = MK.scenes["I9-d"].dep(c); return c.m === "sl" ? ["Annual depreciation = (cost − scrap) ÷ life", "= (" + N(c.cost) + " − " + N(c.salv) + ") ÷ " + c.life + " = " + N(D[0][1]), "Profit = " + N(c.sales) + " − " + N(c.exp) + " − " + N(D[0][1]) + " = " + N(c.sales - c.exp - D[0][1])] : ["Year 1 depreciation = " + c.rate + " % × " + N(c.cost) + " = " + N(D[0][1]), "Book value = " + N(c.cost) + " − " + N(D[0][1]) + " = " + N(D[0][2]), "Year 2 depreciation = " + c.rate + " % × " + N(D[0][2]) + " = " + N(D[1] ? D[1][1] : 0)]; },
    readouts: (s, c) => { const D = MK.scenes["I9-d"].dep(c); return [["Depreciation year 1", N(D[0][1])], ["Final book value", N(D[D.length - 1][2])], ["Net profit year 1", N(c.sales - c.exp - D[0][1])]]; },
    tasks: ["A sprayer costs ₦120,000, lasts 4 years, scrap ₦20,000. Find the annual straight-line depreciation.", "Prepare a profit and loss account from the figures.", "Compare the two methods over 5 years."] });

  /* ===================== I10 Marketing ===================== */
  AK.tour("I10-a", Object.assign({}, FARM, { title: "Meaning and importance of marketing", blurb: "Marketing covers all activities in moving produce from the farm to the consumer: assembling, grading, storing, transporting, processing and selling.", cam: [[0, 3.2, 7.6], [0, 0.6, 0]],
    build(g) { const h = AK.ground(g, { w: 14, d: 9, amp: 0.02, tex: "raked_dirt" }); for (let i = 0; i < 5; i++) { const x = -4 + i * 2; AK.put(g, AK.building("shed", { w: 1.6, d: 1.2, h: 1.1 }), x, -1.2, h); for (let j = 0; j < 3; j++) { const cr = AK.crate([0xe84a3a, 0xf2c21a, 0x6a9a3a, 0xd88a3a, 0xe8dcc0][(i + j) % 5]); cr.position.set(x - 0.4 + j * 0.4, 0.35, -1.0); g.add(cr); } AK.put(g, AK.person({ shirt: [0xd84a8a, 0x2a6ad8, 0xd8a040, 0x5a3a8a, 0x2a8a3a][i] }), x, -0.3, h, Math.PI, 0.55); } const t = AK.tractor(); t.scale.setScalar(0.5); AK.put(g, t, 4.6, 2, h, -0.8); for (let i = 0; i < 4; i++) AK.put(g, AK.sack(0xd8c890), 3 + i * 0.3, 2.6, h); },
    feats: [{ id: "stall", n: "Market stalls (retailers)", p: [-2, 1.6, -1.2], d: "Sell to consumers in small quantities." }, { id: "transp", n: "Transport", p: [4.6, 1.4, 2], d: "Moves produce from farms to markets." }, { id: "bags", n: "Assembled produce", p: [3.4, 0.8, 2.6], d: "Collected from many farms (assembling)." }, { id: "buy", n: "Consumers", p: [0, 1.4, -0.3], d: "Final users of the produce." }],
    notes: ["Importance: links producers and consumers; gives farmers income; reduces waste; makes produce available all year; adds value; creates jobs; earns foreign exchange; encourages production."], tasks: ["Define marketing of agricultural produce.", "Give six importance of marketing."] }));
  const AGENTS = [["assem", "Assemblers (village buyers)", 0.12], ["whole", "Wholesalers", 0.18], ["retail", "Retailers", 0.25], ["coop", "Cooperative instead of middlemen", -0.15]];
  AK.def2d("I10-b", { title: "Marketing agents and their functions", label: "Marketing chain", blurb: "Follow a bag of yams from farmer to consumer. Each agent adds a margin. Remove agents or sell through a cooperative to see the farmer's share change.", values: { assem: 1, whole: 1, retail: 1, coop: 0 },
    controls: AGENTS.map(([k, n]) => ({ type: "toggle", key: k, label: n })),
    calc(c) { const farm = 10000; let p = farm; const steps = [["Farmer", farm]]; if (c.coop) { p *= 1.1; steps.push(["Cooperative", p]); } else { if (c.assem) { p *= 1.12; steps.push(["Assembler", p]); } if (c.whole) { p *= 1.18; steps.push(["Wholesaler", p]); } } if (c.retail) { p *= 1.25; steps.push(["Retailer", p]); } steps.push(["Consumer pays", p]); return { steps, share: farm / p * 100 }; },
    draw(g, s, c, B) { const R = MK.scenes["I10-b"].calc(c), A = B.area, n = R.steps.length, w = (A.w - 10) / n; R.steps.forEach(([nm, p], i) => { const x = A.x + i * w, h = (p / 20000) * (A.h - 80); g.fillStyle = PAL(B)[i % 7]; g.fillRect(x + 6, A.y + A.h - 30 - h, w - 12, h); B.text(N(p), x + w / 2, A.y + A.h - 36 - h, { size: 10, align: "center" }); B.text(nm, x + w / 2, A.y + A.h - 14, { size: n > 5 ? 9 : 10, align: "center", w: 700 }); });
      AK.side(B, "Farmer's share " + f(R.share, 3) + " %", [["Consumer pays " + N(R.steps[n - 1][1]) + " for a bag the farmer sold for ₦10,000", "#ffd27a", true], "Functions of agents: buy and assemble produce, transport, store, grade, finance farmers, bear risk, break bulk, find markets.", "Advantages: convenience, ready market, credit. Disadvantages: high margins, exploitation, hoarding, price manipulation."]); },
    readouts: (s, c) => [["Farmer's share", f(MK.scenes["I10-b"].calc(c).share, 3) + " %"]], tasks: ["Compare the farmer's share with and without middlemen.", "Give three advantages and three disadvantages of marketing agents."] });
  cards("I10-c", { title: "Marketing functions", pick: "Function", head: "Marketing functions", items: [["Assembling", "Collecting small quantities from many farmers into larger lots."], ["Grading and standardisation", "Sorting produce by size, quality and colour; sets fair prices."], ["Processing", "Changing form to add value and keep longer (e.g. cassava to garri)."], ["Storage", "Keeping produce until needed; spreads supply over the year."], ["Transportation", "Moving produce from farms to markets."], ["Packaging", "Protects produce and attracts buyers."], ["Financing", "Providing money for buying, storing and moving produce."], ["Risk bearing", "Accepting losses from price falls, spoilage, theft."], ["Advertising and promotion", "Informing consumers and creating demand."], ["Market information", "Prices and demand data for decisions."], ["Buying and selling", "Exchange of ownership."]], tasks: ["List and explain eight marketing functions.", "How does grading benefit farmers and consumers?"] });
