    draw(g, s, c, B) { const R = Object.entries(EXM).map(([k, [n, , cost, ad]]) => { const reach = c.bud / cost; return [n.split(" (")[0], reach, reach * ad, k]; }); AK.barChart(B, B.area.x, 12, B.area.w, B.H - 26, R.map(([n, , ad, k]) => [n, ad, k === c.m ? B.P.amber : B.P.blue]), { title: "Farmers who adopt the practice", fmt: (v) => Math.round(v).toLocaleString("en-GB") }); const M = EXM[c.m], reach = c.bud / M[2];
      AK.side(B, M[0], [["Reaches " + Math.round(reach).toLocaleString("en-GB") + " farmers at " + N(M[2]) + " each; about " + Math.round(M[3] * 100) + " % adopt", "#ffd27a", true], { indiv: "Advantages: personal, builds trust, solves specific problems. Disadvantages: costly, few farmers reached.", group: "Advantages: farmers learn from each other; seeing is believing. Disadvantages: needs organising; not all attend.", mass: "Advantages: reaches very many quickly and cheaply. Disadvantages: one-way, no feedback, low adoption, needs radio or literacy." }[c.m], "Best results come from combining methods."]); },
